  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''STREAMING_INGEST_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''STREAMING_INGEST_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''STREAMING_INGEST_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''STREAMING_INGEST_APP'' AND "comment"=''oneshot-source:10_streaming_ingest''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.STREAMING_INGEST_APP FROM ''@__TARGET__.APP_STAGE/source/2df1dbc0563a06fa/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:10_streaming_ingest''; ALTER STREAMLIT __TARGET__.STREAMING_INGEST_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
